schema:
CREATE TABLE Divisions (id INTEGER NOT NULL PRIMARY KEY, division_name TEXT NOT NULL);
CREATE TABLE Athletes (id INTEGER NOT NULL PRIMARY KEY, full_name TEXT NOT NULL, division_id INTEGER NOT NULL, score_pts INTEGER DEFAULT NULL, reach_mm INTEGER DEFAULT NULL, FOREIGN KEY (division_id) REFERENCES Divisions (id));
CREATE TABLE Badges (id INTEGER NOT NULL PRIMARY KEY, badge_title TEXT NOT NULL);
CREATE TABLE Athlete_Badges (athlete_id INTEGER NOT NULL, badge_id INTEGER NOT NULL, FOREIGN KEY (athlete_id) REFERENCES Athletes (id), FOREIGN KEY (badge_id) REFERENCES Badges (id));
